u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0443\\u044e \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u044e \\u043f\\u043e \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u0438\\u0442\\u0435\\u043b\\u044c\\u0441\\u043a\\u0438\\u043c \\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u0430\\u043c, \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430 \\u043f\\u043e\\u0441\\u0442\\u0430\\u0432\\u043b\\u044f\\u0435\\u043c\\u043e\\u0439 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u0438, \\u0440\\u0430\\u0441\\u0448\\u0438\\u0440\\u0435\\u043d\\u0438\\u0435 \\u0438 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0435 \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0440\\u0430\\u0441\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u044c\\u044e \\u0432 \\u0440\\u0435\\u0433\\u0438\\u043e\\u043d\\u0435, \\u0443\\u043b\\u0443\\u0447\\u0448\\u0435\\u043d\\u0438\\u0435 \\u043e\\u0431\\u0441\\u043b\\u0443\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u043a\\u0430\\u043a \\u0446\\u0435\\u043b\\u044b\\u0445, \\u0442\\u0430\\u043a \\u0438 \\u0440\\u043e\\u0437\\u043d\\u0438\\u0447\\u043d\\u044b\\u0445 \\u043a\\u043b\\u0438\\u0435\\u043d\\u0442\\u043e\\u0432. \\u041c\\u044b \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0435\\u043c \\u0432 \\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u043e\\u043c \\u0441 \\u043a\\u043e\\u0440\\u0435\\u0439\\u0441\\u043a\\u0438\\u043c\\u0438, \\u044f\\u043f\\u043e\\u043d\\u0441\\u043a\\u0438\\u043c\\u0438 \\u0438 \\u0435\\u0432\\u0440\\u043e\\u043f\\u0435\\u0439\\u0441\\u043a\\u0438\\u043c\\u0438 \\u043f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0438\\u0442\\u0435\\u043b\\u044f\\u043c\\u0438 \\u0437\\u0430\\u043f\\u0430\\u0441\\u043d\\u044b\\u0445 \\u0447\\u0430\\u0441\\u0442\\u0435\\u0439 \\u0438 \\u0442\\u043e\\u0440\\u0433\\u043e\\u0432\\u044b\\u043c\\u0438 \\u043c\\u0430\\u0440\\u043a\\u0430\\u043c\\u0438. \\u041c\\u044b \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0435\\u043c \\u0431\\u043e\\u043b\\u0435\\u0435 15 \\u043b\\u0435\\u0442, \\u0443\\u0441\\u043f\\u0435\\u0448\\u043d\\u043e \\u0440\\u0430\\u0437\\u0432\\u0438\\u0432\\u0430\\u0435\\u043c, \\u0440\\u0430\\u0441\\u0448\\u0438\\u0440\\u044f\\u0435\\u043c \\u0430\\u0441\\u0441\\u043e\\u0440\\u0442\\u0438\\u043c\\u0435\\u043d\\u0442 \\u043f\\u0440\\u043e\\u0434\\u0443\\u043a\\u0446\\u0438\\u0438 \\u0438 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440 \\u0443\\u0441\\u043b\\u0443\\u0433.<\\/p><p>\\u0422\\u043e\\u0440\\u0433\\u043e\\u0432\\u0430\\u044f \\u0433\\u0440\\u0443\\u043f\\u043f\\u0430\\u00a0<strong>UNOMAX<\\/strong> <strong>TECHNICS<\\/strong> \\u043f\\u0440\\u043e\\u0432\\u0435\\u043b\\u0430 \\u043c\\u043d\\u043e\\u0436\\u0435\\u0441\\u0442\\u0432\\u043e \\u0432\\u0441\\u0442\\u0440\\u0435\\u0447, \\u0441\\u0435\\u043c\\u0438\\u043d\\u0430\\u0440\\u043e\\u0432 \\u0438 \\u0442\\u0440\\u0435\\u043d\\u0438\\u043d\\u0433\\u043e\\u0432 \\u0441 \\u043f\\u0435\\u0440\\u0441\\u043e\\u043d\\u0430\\u043b\\u043e\\u043c \\u043d\\u0430 \\u0440\\u0435\\u0433\\u0443\\u043b\\u044f\\u0440\\u043d\\u043e\\u0439 \\u043e\\u0441\\u043d\\u043e\\u0432\\u0435, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u0435 \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e \\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442 \\u0440\\u0430\\u0437\\u0432\\u0438\\u0442\\u0438\\u044e \\u043d\\u0430\\u0448\\u0435\\u0439 \\u043a\\u043e\\u043c\\u043f\\u0430\\u043d\\u0438\\u0438. \\u0412 \\u043d\\u0430\\u0448\\u0435\\u043c \\u043e\\u0444\\u0438\\u0441\\u0435 \\u0435\\u0441\\u0442\\u044c \\u0432\\u044b\\u0441\\u0442\\u0430\\u0432\\u043e\\u0447\\u043d\\u044b\\u0435 \\u0441\\u0442\\u0435\\u043d\\u0434\\u044b \\u0441 \\u0432\\u044b\\u043f\\u0443\\u0441\\u043a\\u043e\\u043c \\u0432\\u0441\\u0435\\u0445 \\u043d\\